package com.barolab.morningcard;
import android.graphics.*;
import android.text.*;

/** Original geometry scenes and commissioned original photo backgrounds; legacy theme IDs stay stable. */
final class CardRenderer {
 static final String[] THEMES={"봄꽃 가지","여름 연못","가을 숲","겨울 산책","아침 바다","달빛 정원","꽃빛 안부 · 사진","고요한 바다 · 사진","가을 편지 · 사진"};
 private static volatile android.content.res.Resources resources;
 static void initialize(android.content.res.Resources value){resources=value;}
 static Bitmap render(CardState state){
  if(!CardState.renderable(state.text))throw new IllegalArgumentException("Too many line breaks or characters");
  TextPaint ink=new TextPaint(Paint.ANTI_ALIAS_FLAG);ink.setColor(state.highContrast?Color.rgb(18,34,34):Color.rgb(59,78,70));ink.setTypeface(Typeface.create("serif",Typeface.NORMAL));ink.setTextLocale(java.util.Locale.KOREAN);ink.setTextSize(state.font);
  StaticLayout.Builder layout=StaticLayout.Builder.obtain(state.text,0,state.text.length(),ink,800).setAlignment(Layout.Alignment.ALIGN_CENTER).setLineSpacing(16,1.16f).setIncludePad(false);if(android.os.Build.VERSION.SDK_INT>=33)layout.setLineBreakConfig(new android.graphics.text.LineBreakConfig.Builder().setLineBreakWordStyle(android.graphics.text.LineBreakConfig.LINE_BREAK_WORD_STYLE_PHRASE).build());StaticLayout body=layout.build();
  boolean sender=state.includeName&&!state.name.trim().isEmpty();int content=body.getHeight()+(sender?110:0),height=Math.max(1350,content+600);if(height>6000)throw new IllegalArgumentException("Card exceeds safe render size");Bitmap image=Bitmap.createBitmap(1080,height,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(image);if(state.theme>=6)photo(c,state.theme,height);else scene(c,state.theme,height);
  Paint panel=new Paint(Paint.ANTI_ALIAS_FLAG);panel.setColor(state.theme>=6?(state.highContrast?0xe8fffdf7:0xcffffdf7):(state.highContrast?Color.WHITE:Color.rgb(255,252,243)));if(state.theme<6)c.drawRoundRect(65,240,1015,height-220,44,44,panel);else c.drawRoundRect(90,Math.max(220,(height-content)/2f-65),990,Math.min(height-170,(height+content)/2f+65),34,34,panel);
  Paint label=new Paint(Paint.ANTI_ALIAS_FLAG);label.setColor(state.theme==5?Color.rgb(255,244,219):Color.rgb(42,77,66));label.setTextSize(34);label.setTextAlign(Paint.Align.CENTER);label.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));c.drawText("마음을 전합니다",540,205,label);
  float y=(height-content)/2f;c.save();c.translate(140,y);body.draw(c);c.restore();
  if(sender){label.setColor(Color.rgb(42,77,66));label.setTextSize(38);c.drawText(state.name.trim()+" 드림",540,y+body.getHeight()+78,label);}if(state.theme>=6){panel.setColor(0xe8fffdf7);c.drawRoundRect(410,height-298,670,height-239,18,18,panel);}label.setColor(Color.rgb(42,77,66));label.setTextSize(28);c.drawText("오늘의 안부",540,height-260,label);return image;
 }
 private static void photo(Canvas canvas,int theme,int height){android.content.res.Resources res=resources;int[] ids={R.drawable.card_photo_flower,R.drawable.card_photo_sea,R.drawable.card_photo_autumn};if(res==null||theme<6||theme>8){scene(canvas,0,height);return;}BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap background=BitmapFactory.decodeResource(res,ids[theme-6],options);if(background==null){scene(canvas,0,height);return;}float scale=Math.max(1080f/background.getWidth(),height/(float)background.getHeight());float w=background.getWidth()*scale,h=background.getHeight()*scale;Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);canvas.drawBitmap(background,null,new RectF((1080-w)/2,(height-h)/2,(1080+w)/2,(height+h)/2),paint);background.recycle();}
 private static void color(Paint p,int rgb){p.setColor(rgb);p.setStyle(Paint.Style.FILL);}
 private static void flower(Canvas c,float x,float y,float size,int petals,Paint p,int tint){color(p,tint);for(int i=0;i<petals;i++){c.save();c.rotate(i*360f/petals,x,y);c.drawOval(x-size*.35f,y-size,x+size*.35f,y+size*.15f,p);c.restore();}color(p,Color.rgb(218,166,74));c.drawCircle(x,y,size*.22f,p);}
 private static void scene(Canvas c,int theme,int h){Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);switch(theme){
  case 0:c.drawColor(Color.rgb(250,229,228));color(p,Color.rgb(128,101,84));p.setStrokeWidth(18);c.drawLine(0,40,320,260,p);c.drawLine(1080,h-20,790,h-240,p);for(int i=0;i<7;i++){flower(c,35+i*40,45+i*25,34,5,p,Color.rgb(255,248-i*5,247-i*5));flower(c,1040-i*34,h-70-i*20,30,5,p,Color.rgb(238,162+i*6,181));}break;
  case 1:c.drawColor(Color.rgb(208,236,226));color(p,Color.rgb(99,161,150));for(int y=h-200;y<h;y+=45)c.drawOval(-180,y,1300,y+30,p);color(p,Color.rgb(77,132,89));c.drawOval(20,h-190,245,h-95,p);c.drawOval(800,75,1060,160,p);flower(c,155,h-160,43,8,p,Color.rgb(245,199,211));flower(c,925,100,36,8,p,Color.rgb(255,244,221));break;
  case 2:c.drawColor(Color.rgb(250,226,184));color(p,Color.rgb(117,91,64));c.drawRect(18,0,43,h,p);c.drawRect(1040,0,1063,h,p);for(int i=0;i<12;i++){color(p,i%2==0?Color.rgb(200,103,46):Color.rgb(223,158,55));float x=40+i*89;c.save();c.rotate(i*19,x,100);c.drawOval(x-37,45,x+37,160,p);c.restore();c.drawOval(x-30,h-150-(i%3)*24,x+30,h-70-(i%3)*24,p);}break;
  case 3:c.drawColor(Color.rgb(219,233,239));color(p,Color.rgb(164,189,197));Path mountain=new Path();mountain.moveTo(0,220);mountain.lineTo(190,20);mountain.lineTo(390,220);mountain.close();c.drawPath(mountain,p);color(p,Color.WHITE);for(int i=0;i<18;i++)c.drawCircle((i*73)%1080,40+(i%3)*45,5,p);color(p,Color.rgb(85,126,118));for(int i=0;i<4;i++){float x=90+i*290;Path tree=new Path();tree.moveTo(x,h-220);tree.lineTo(x-75,h-60);tree.lineTo(x+75,h-60);tree.close();c.drawPath(tree,p);}color(p,Color.WHITE);c.drawOval(-100,h-85,1180,h+100,p);break;
  case 4:c.drawColor(Color.rgb(241,225,194));color(p,Color.rgb(235,163,87));c.drawCircle(835,125,80,p);for(int i=0;i<5;i++){color(p,Color.rgb(85+i*15,151+i*9,170+i*9));Path wave=new Path();float y=h-240+i*60;wave.moveTo(0,y);wave.cubicTo(300,y-65,650,y+80,1080,y);wave.lineTo(1080,h);wave.lineTo(0,h);wave.close();c.drawPath(wave,p);}color(p,Color.rgb(74,101,103));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(6);c.drawArc(120,80,190,125,190,150,false,p);c.drawArc(190,80,260,125,200,150,false,p);break;
  default:c.drawColor(Color.rgb(40,61,87));color(p,Color.rgb(255,240,192));c.drawCircle(870,120,75,p);color(p,Color.rgb(40,61,87));c.drawCircle(902,95,69,p);color(p,Color.rgb(229,233,202));for(int i=0;i<17;i++)c.drawCircle((i*197)%1080,25+(i%5)*34,3+i%3,p);color(p,Color.rgb(68,105,98));c.drawOval(-200,h-160,1280,h+210,p);for(int i=0;i<7;i++)flower(c,85+i*150,h-72,20,7,p,Color.rgb(249,242,209));break;
 }}
}
